package dev.raf.radar;
import android.content.*;import android.graphics.*;import android.view.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import org.maplibre.android.camera.CameraUpdateFactory;import org.maplibre.android.geometry.LatLng;
public class MapAnchorTest {
 @Test public void draggingLabelKeepsCoordinateAndMovingPointClearsOldPrice()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);s.prefs.edit().clear().putBoolean("autoUpdate",false).putBoolean("sounds",false).commit();AccountClient.save(s,new JSONObject().put("user",new JSONObject().put("id",999).put("name","Fixture")).put("session","a".repeat(64)));ScreenTest.grantAccess();Point p=new Point("anchor-fixture","Fixture",55,61,false);s.update(p);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){for(int i=0;i<20;i++){final boolean[] ready={false};scenario.onActivity(a->ready[0]=a.map!=null);if(ready[0])break;Thread.sleep(100);}scenario.onActivity(a->{assertNotNull(a.map);a.map.moveCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(p.lat,p.lon),13));a.refreshMarkers();PointF anchor=a.map.getProjection().toScreenLocation(new LatLng(p.lat,p.lon));PointF label=a.labelPosition(p,anchor,a.pointBitmaps.get(p.id));long at=android.os.SystemClock.uptimeMillis();a.pointOverlay.dispatchTouchEvent(MotionEvent.obtain(at,at,0,label.x,label.y,0));a.pointOverlay.dispatchTouchEvent(MotionEvent.obtain(at,at+20,2,label.x+a.dp(40),label.y+a.dp(20),0));a.pointOverlay.dispatchTouchEvent(MotionEvent.obtain(at,at+40,1,label.x+a.dp(40),label.y+a.dp(20),0));assertEquals(40,a.store.prefs.getFloat("labelX:"+p.id,0),1);Point saved=a.store.points().stream().filter(x->x.id.equals(p.id)).findFirst().get();assertEquals(55,saved.lat,0);assertEquals(61,saved.lon,0);a.store.readings(p.id,java.util.Collections.singletonList(new Store.Reading("econom",200,null,System.currentTimeMillis(),"fixture")));saved.lat+=.1;a.store.update(saved);assertTrue(a.store.readings(p.id).isEmpty());assertFalse(a.store.prefs.contains("trendValue:"+p.id));a.store.prefs.edit().putBoolean("forecast",true).apply();a.refreshMarkers();});ScreenTest.capture("anchored-area");}finally{AccountClient.clear(s);s.remove(p.id);}}
}
